class Solution {
    public boolean isSymmetric(TreeNode root) {
        if (root == null) {
            return true;
        }

        Deque<TreeNode[]> stack = new ArrayDeque<>();
        stack.push(new TreeNode[] {root.left, root.right});

        while (!stack.isEmpty()) {
            TreeNode[] pair = stack.pop();
            TreeNode left = pair[0];
            TreeNode right = pair[1];

            if (left == null && right == null) {
                continue;
            }
            if (left == null || right == null || left.val != right.val) {
                return false;
            }

            stack.push(new TreeNode[] {left.left, right.right});
            stack.push(new TreeNode[] {left.right, right.left});
        }

        return true;
    }
}

import java.util.*;

class Solution {
    public boolean isSymmetric(TreeNode root) {
        if (root == null) {
            return true;
        }

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            int size = queue.size();
            List<Integer> level = new ArrayList<>();
            boolean hasNext = false;

            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();
                if (node == null) {
                    level.add(null);
                    continue;
                }

                level.add(node.val);
                if (node.left != null || node.right != null) {
                    hasNext = true;
                }
                queue.offer(node.left);
                queue.offer(node.right);
            }

            int left = 0;
            int right = level.size() - 1;
            while (left < right) {
                if (!Objects.equals(level.get(left), level.get(right))) {
                    return false;
                }
                left++;
                right--;
            }

            if (!hasNext) {
                break;
            }
        }

        return true;
    }
}
